const lead = $input.first().json;
const required = ['contact_id', 'result_id', 'approval_id', 'assigned_user_id', 'category'];
const missing = required.filter((key) => !lead[key]);

if (missing.length) {
  throw new Error(`Invalid follow-up payload. Missing: ${missing.join(', ')}`);
}
if (String(lead.category).toLowerCase() !== 'hot') {
  throw new Error('Only hot leads can enter the Enrollment follow-up workflow');
}

return [{ json: {
  ...lead,
  contact_id: String(lead.contact_id),
  result_id: String(lead.result_id),
  approval_id: String(lead.approval_id),
  assigned_user_id: String(lead.assigned_user_id),
  action: 'enrollment_follow_up',
  requested_at: new Date().toISOString()
} }];

const contact = $input.first().json;
const request = $('Validate Follow-up Payload').first().json;
const existingTags = Array.isArray(contact.tags) ? contact.tags : [];
const tags = [...new Set([...existingTags, 'eny-follow-up-queued'])];

return [{ json: {
  ...request,
  contact_name: contact.name || [contact.firstName, contact.lastName].filter(Boolean).join(' '),
  email: contact.email || null,
  tags
} }];
